import sys
from math import log10, floor

def rev(n):
    r = 0
    while n > 0:
        r = r * 10 + n % 10
        n //= 10
    return r

def generate_up_to(limit):
    # Generate all numbers <= limit that appear on the board.
    # We iterate row by row, column by column, stopping when the value exceeds limit.
    # Since the sequence grows at least by factor ~2 (often much more due to digit reversal),
    # the total count is manageable for limit = 10^10.
    numbers = set()
    limit = limit

    for i in range(1, limit + 2):  # row index
        val = i
        if val > limit:
            break
        numbers.add(val)
        while True:
            val = val + rev(val)
            if val > limit:
                break
            numbers.add(val)
            # Safety break to prevent infinite loops if logic fails, though math guarantees growth
            if val > limit * 2: 
                break
    return sorted(list(numbers))

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        Q = int(next(iterator))
    except StopIteration:
        return

    queries = []
    max_b = 0
    for _ in range(Q):
        a = int(next(iterator))
        b = int(next(iterator))
        queries.append((a, b))
        if b > max_b:
            max_b = b

    # Precompute all unique numbers up to max_b
    if max_b == 0:
        # Should not happen based on constraints
        all_nums = []
    else:
        all_nums = generate_up_to(max_b)

    # Convert to a list for binary search
    # Since we need count in [A, B], we can use bisect
    import bisect

    def count_in_range(a, b):
        l = bisect.bisect_left(all_nums, a)
        r = bisect.bisect_right(all_nums, b)
        return r - l

    results = []
    for a, b in queries:
        results.append(count_in_range(a, b))

    for res in results:
        print(res)

if __name__ == '__main__':
    solve()
